import*as THREE from'three';
const COLORS={wood:'#9b6841',woodLight:'#c18b55',metal:'#566a70',yellow:'#e4c24d',blue:'#4f8397',paper:'#e9e1cf'};
const toon=color=>new THREE.MeshToonMaterial({color});
function part(group,geometry,material,position,edge=true){const mesh=new THREE.Mesh(geometry,material);mesh.position.set(...position);mesh.castShadow=true;mesh.receiveShadow=true;group.add(mesh);if(edge){const lines=new THREE.LineSegments(new THREE.EdgesGeometry(geometry,18),new THREE.LineBasicMaterial({color:'#26353a',transparent:true,opacity:.55}));mesh.add(lines)}return mesh}
export function createCrate(){const group=new THREE.Group(),body=part(group,new THREE.BoxGeometry(1,.62,.76),toon(COLORS.wood),[0,.31,0]);for(const x of[-.38,0,.38])part(group,new THREE.BoxGeometry(.08,.66,.8),toon(COLORS.woodLight),[x,.32,0]);const lidPivot=new THREE.Group();lidPivot.position.set(0,.65,-.36);group.add(lidPivot);const lid=part(lidPivot,new THREE.BoxGeometry(1.06,.1,.78),toon(COLORS.woodLight),[0,0,.36]);const contents=new THREE.Group();contents.visible=false;contents.position.y=.45;group.add(contents);const tape=part(contents,new THREE.TorusGeometry(.13,.055,8,20),toon(COLORS.yellow),[0,.12,0],false);tape.rotation.x=Math.PI/2;part(contents,new THREE.BoxGeometry(.25,.06,.13),toon(COLORS.metal),[.18,.12,0],false);return{group,body,lidPivot,lid,contents,progress:0,target:0,hasContents:true,update(dt){this.progress=THREE.MathUtils.lerp(this.progress,this.target,1-Math.exp(-dt*8));lidPivot.rotation.x=-this.progress*Math.PI*.62;contents.visible=this.hasContents&&this.progress>.22;contents.position.y=.45+this.progress*.22},open(){this.target=1},takeContents(){this.hasContents=false}}}
export function createPallet(){const group=new THREE.Group();for(const z of[-.32,0,.32])part(group,new THREE.BoxGeometry(1.25,.09,.22),toon(COLORS.woodLight),[0,.16,z]);for(const x of[-.48,0,.48])part(group,new THREE.BoxGeometry(.18,.13,.86),toon(COLORS.wood),[x,.065,0]);return group}
export function createBucket(color=COLORS.blue){const group=new THREE.Group();part(group,new THREE.CylinderGeometry(.24,.19,.38,16),toon(color),[0,.2,0]);const handle=part(group,new THREE.TorusGeometry(.25,.022,6,18,Math.PI),toon(COLORS.metal),[0,.39,0],false);handle.rotation.z=Math.PI;return group}
export function createBarrier(){const group=new THREE.Group();part(group,new THREE.BoxGeometry(1.35,.18,.16),toon(COLORS.yellow),[0,.78,0]);for(const x of[-.53,.53])part(group,new THREE.BoxGeometry(.12,1.35,.12),toon(COLORS.metal),[x,.68,0]);for(const x of[-.53,.53])part(group,new THREE.BoxGeometry(.52,.09,.18),toon(COLORS.metal),[x,.045,0]);return group}
